insert into public.areas (id, name, short, vibe, description, ppm, rent, img, x, y, tags, dna, sort) values
  ('center', 'القلعة ومركز المدينة', 'المركز', 'القلب التاريخي ومركز الأعمال', 'حول قلعة أربيل المسجّلة في اليونسكو. الجزء الأكثر حيوية واتصالاً في المدينة، بين الأسواق والمكاتب وأحدث الأبراج.', 1850, 6.5, 'https://images.unsplash.com/photo-1449824913935-59a10b8d2000?auto=format&fit=crop&w=900&q=70', 50, 50, array['قريب من كل شي','مكاتب','تراث']::text[], '{"family":5,"convenience":10,"green":4,"dining":9,"growth":7,"quiet":3}'::jsonb, 0),
  ('ankawa', 'عينكاوة', 'عينكاوة', 'حي منفتح بمقاهٍ ومطاعم', 'قريب من المطار، ويضم مطاعم ومقاهي كثيرة ومدارس وفنادق وسكاناً من جنسيات مختلفة.', 1650, 6.4, 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?auto=format&fit=crop&w=900&q=70', 39, 29, array['قرب المطار','مطاعم','مدارس']::text[], '{"family":7,"convenience":8,"green":5,"dining":10,"growth":7,"quiet":5}'::jsonb, 1),
  ('gulan', 'كولان', 'كولان', 'أبراج ومولات وشارع الستين', 'الواجهة الحديثة لأربيل: سكن في الأبراج قرب المولات والفنادق ومتنزه سامي عبد الرحمن.', 1950, 7, 'https://images.unsplash.com/photo-1460317442991-0ec209397118?auto=format&fit=crop&w=900&q=70', 38, 46, array['أبراج','مولات','قرب المتنزه']::text[], '{"family":6,"convenience":9,"green":6,"dining":8,"growth":9,"quiet":4}'::jsonb, 2),
  ('bakhtiari', 'بختياري', 'بختياري', 'حي عائلي راسخ', 'شوارع سكنية هادئة وأسواق محلية ومدارس. مفضّل عند العوائل اللي تريد مساحة قريبة من المدينة.', 1400, 4.6, 'https://images.unsplash.com/photo-1568605114967-8130f3a36994?auto=format&fit=crop&w=900&q=70', 43, 61, array['عوائل','مدارس','هادئ']::text[], '{"family":9,"convenience":7,"green":6,"dining":6,"growth":6,"quiet":7}'::jsonb, 3),
  ('iskan', 'إسكان', 'إسكان', 'سكني قريب من المركز وبسعر مناسب', 'حي عملي قريب من المركز، فيه بيوت وشقق متوسطة الارتفاع بأسعار مناسبة.', 1300, 4.5, 'https://images.unsplash.com/photo-1576941089067-2de3c901e126?auto=format&fit=crop&w=900&q=70', 58, 45, array['قريب من المركز','سعر مناسب']::text[], '{"family":8,"convenience":8,"green":4,"dining":6,"growth":6,"quiet":6}'::jsonb, 4),
  ('pirmam', 'طريق پيرمام', 'پيرمام', 'فلل وهواء نقي وإطلالات', 'باتجاه الجبال شمالاً: مجمعات فلل مسيّجة وقطع أكبر وأمسيات صيفية ألطف.', 1150, 4, 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=900&q=70', 60, 20, array['فلل','مسيّج','إطلالات']::text[], '{"family":9,"convenience":5,"green":9,"dining":4,"growth":8,"quiet":9}'::jsonb, 5),
  ('kirkuk', 'طريق كركوك', 'طريق كركوك', 'مجمعات جديدة مخططة', 'هنا تنبني أغلب المجمعات الكبيرة الجديدة. مساحة أكبر بنفس الميزانية، والخدمات تكبر ويّاها.', 1050, 3.8, 'https://images.unsplash.com/photo-1570129477492-45c003edd2be?auto=format&fit=crop&w=900&q=70', 50, 87, array['مشاريع جديدة','مساحة','نمو']::text[], '{"family":9,"convenience":6,"green":7,"dining":4,"growth":9,"quiet":8}'::jsonb, 6),
  ('kasnazan', 'كسنزان', 'كسنزان', 'ضواحٍ واسعة وفلل', 'شرق المدينة على طريق كويه: هادئ وأخضر وواسع، فيه مجمعات فلل ومساحة للتوسّع.', 950, 3.6, 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=900&q=70', 79, 65, array['هادئ','فلل','أخضر']::text[], '{"family":9,"convenience":4,"green":8,"dining":3,"growth":8,"quiet":10}'::jsonb, 7);
